#include <asndlib.h>

#include "audio.h"
#include "audio_data.h"

/* The approved assets are signed 16-bit mono PCM at 32000 Hz.
 * audio_data.c is generated by tools/embed_audio.py, which converts
 * the WAV little-endian samples to ASND's native big-endian format.
 * The arrays have 32-byte alignment and padding for DSP reads.
 * Embedded heartbeat PCM has mild added harmonics for small TV speakers;
 * the approved WAV assets in assets/approved_wav remain unchanged.
 */
#define AUDIO_RATE_HZ 32000
#define FIRST_EFFECT_VOICE 4
#define LAST_EFFECT_VOICE 15
#define VOICE_HEARTBEAT 1
#define VOICE_THRUST 2
#define VOICE_SHIP_EXPLOSION 3

typedef struct {
    const unsigned char *data;
    unsigned int bytes;
    int volume;
} AudioClip;

typedef enum {
    CLIP_LARGE, CLIP_MEDIUM, CLIP_SMALL, CLIP_HEART_HIGH,
    CLIP_HEART_LOW, CLIP_LASER, CLIP_EXPLOSION, CLIP_THRUST
} ClipId;

static int s_heartbeat_ticks;
static int s_heartbeat_high;
static int s_thrust_active;

static AudioClip get_clip(ClipId which)
{
    AudioClip clip;
    clip.data = 0;
    clip.bytes = 0;
    clip.volume = 190;

    switch (which) {
    case CLIP_LARGE:
        clip.data = sfx_asteroid_large;
        clip.bytes = sfx_asteroid_large_bytes;
        clip.volume = 195;
        break;
    case CLIP_MEDIUM:
        clip.data = sfx_asteroid_medium;
        clip.bytes = sfx_asteroid_medium_bytes;
        clip.volume = 195;
        break;
    case CLIP_SMALL:
        clip.data = sfx_asteroid_small;
        clip.bytes = sfx_asteroid_small_bytes;
        clip.volume = 195;
        break;
    case CLIP_HEART_HIGH:
        clip.data = sfx_heartbeat_high;
        clip.bytes = sfx_heartbeat_high_bytes;
        clip.volume = 215;
        break;
    case CLIP_HEART_LOW:
        clip.data = sfx_heartbeat_low;
        clip.bytes = sfx_heartbeat_low_bytes;
        clip.volume = 215;
        break;
    case CLIP_LASER:
        clip.data = sfx_laser_shot;
        clip.bytes = sfx_laser_shot_bytes;
        clip.volume = 160;
        break;
    case CLIP_EXPLOSION:
        clip.data = sfx_ship_explosion;
        clip.bytes = sfx_ship_explosion_bytes;
        clip.volume = 220;
        break;
    case CLIP_THRUST:
        clip.data = sfx_thrust_loop;
        clip.bytes = sfx_thrust_loop_bytes;
        clip.volume = 110;
        break;
    }
    return clip;
}

static void play_on_voice(int voice, ClipId which)
{
    AudioClip clip = get_clip(which);
    if (!clip.data || !clip.bytes) return;
    /* No callback: one-shot sound; voices are reclaimed when finished. */
    ASND_SetVoice(voice, VOICE_MONO_16BIT, AUDIO_RATE_HZ, 0,
                  (void *)clip.data, (s32)clip.bytes,
                  clip.volume, clip.volume, 0);
}

static void play_effect(ClipId which)
{
    int voice;
    /* Do not steal dedicated heartbeat, thrust, or ship-death voices. */
    for (voice = FIRST_EFFECT_VOICE; voice <= LAST_EFFECT_VOICE; ++voice) {
        if (ASND_StatusVoice(voice) == SND_UNUSED) {
            play_on_voice(voice, which);
            return;
        }
    }
    /* If all 12 effects are busy, drop just this event. */
}

void audio_reset(void)
{
    int voice;
    for (voice = VOICE_HEARTBEAT; voice <= LAST_EFFECT_VOICE; ++voice)
        ASND_StopVoice(voice);
    s_heartbeat_ticks = 16;
    s_heartbeat_high = 0;
    s_thrust_active = 0;
}

void audio_init(void)
{
    ASND_Init();
    audio_reset();
    /* ASND_Init starts paused; enable the audio mixer explicitly. */
    ASND_Pause(0);
}

static int heartbeat_interval(const Game *game)
{
    int total = game->wave;
    int remaining = 0;
    int i;
    if (total > 10) total = 10;
    total *= 4; /* Large = four smallest asteroid fragments. */

    for (i = 0; i < GAME_MAX_ASTEROIDS; ++i) {
        const GameAsteroid *asteroid = &game->asteroids[i];
        if (!asteroid->active) continue;
        if (asteroid->size == ASTEROID_LARGE) remaining += 4;
        else if (asteroid->size == ASTEROID_MEDIUM) remaining += 2;
        else remaining += 1;
    }
    /* As rocks are cleared, gradually shorten the heartbeat interval.
     * Splitting alone does not incorrectly change the remaining mass.
     * 42 ticks (700 ms) at wave start -> 14 ticks (233 ms) at end. */
    if (remaining > total) remaining = total;
    return 14 + (28 * remaining) / total;
}

void audio_tick(const Game *game, GameInput controls)
{
    const unsigned events = game->sound_events;
    int thrusting;

    /* Read event flags immediately after game_tick. Multiple simulation
     * updates per video frame each get their own event dispatch (PAL-safe). */
    if (events & GAME_SFX_SHOT) play_effect(CLIP_LASER);
    if (events & GAME_SFX_LARGE_HIT) play_effect(CLIP_LARGE);
    if (events & GAME_SFX_MEDIUM_HIT) play_effect(CLIP_MEDIUM);
    if (events & GAME_SFX_SMALL_HIT) play_effect(CLIP_SMALL);
    if (events & GAME_SFX_SHIP_EXPLODE)
        play_on_voice(VOICE_SHIP_EXPLOSION, CLIP_EXPLOSION);

    /* Use a reserved channel so the thrust sound cannot be cut off by hits. */
    thrusting = controls.thrust && game->ship_alive && !game->game_over;
    if (!thrusting) {
        if (s_thrust_active) ASND_StopVoice(VOICE_THRUST);
        s_thrust_active = 0;
    } else {
        if (ASND_StatusVoice(VOICE_THRUST) == SND_UNUSED)
            play_on_voice(VOICE_THRUST, CLIP_THRUST);
        s_thrust_active = 1;
    }

    /* Keep the last ship explosion audible after game over, but no heartbeat. */
    if (game->game_over || game_asteroid_count(game) == 0) return;

    if (--s_heartbeat_ticks <= 0) {
        play_on_voice(VOICE_HEARTBEAT,
                      s_heartbeat_high ? CLIP_HEART_HIGH : CLIP_HEART_LOW);
        s_heartbeat_high ^= 1;
        s_heartbeat_ticks = heartbeat_interval(game);
    }
}

void audio_shutdown(void)
{
    int voice;
    for (voice = VOICE_HEARTBEAT; voice <= LAST_EFFECT_VOICE; ++voice)
        ASND_StopVoice(voice);
    ASND_End();
}
